#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

char* predictPartyVictory(char* senate) {
    int n = (int)strlen(senate);
    int* r = (int*)malloc((n + n + 2) * sizeof(int));
    int* d = (int*)malloc((n + n + 2) * sizeof(int));
    int rh = 0, rt = 0, dh = 0, dt = 0;
    for (int i = 0; i < n; ++i) {
        if (senate[i] == 'R') r[rt++] = i;
        else d[dt++] = i;
    }
    while (rh < rt && dh < dt) {
        int ri = r[rh++];
        int di = d[dh++];
        if (ri < di) r[rt++] = ri + n;
        else d[dt++] = di + n;
    }
    free(r);
    free(d);
    return (rh < rt) ? "Radiant" : "Dire";
}

