class Solution {
    public String predictPartyVictory(String senate) {
        int n = senate.length();
        ArrayDeque<Integer> radiant = new ArrayDeque<>();
        ArrayDeque<Integer> dire = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') radiant.addLast(i);
            else dire.addLast(i);
        }
        while (!radiant.isEmpty() && !dire.isEmpty()) {
            int r = radiant.removeFirst();
            int d = dire.removeFirst();
            if (r < d) radiant.addLast(r + n);
            else dire.addLast(d + n);
        }
        return radiant.isEmpty() ? "Dire" : "Radiant";
    }
}

